INSERT INTO "experiences" ("slug","role","place","type","image","image_alt","text","details","links","sort_order","related_project_slugs") VALUES ('web-development-instructor','Web Development Instructor','Ethio Computer School','Teaching · Digital skills','/images/placeholder.png','Editorial illustration of an instructor and learners building a web page together.','Taught web development through practical, project-led learning at a school that describes itself as Ethiopia’s leading digital skills school. The course focuses on building real projects rather than only studying theory.','["Delivered web-development instruction through practical, project-led learning.","The published course is titled “Learn Web Development Through Real Projects.”"]'::jsonb,'[{"label":"Course page","href":"https://www.ethiocomputer.school/courses/web-development"},{"label":"Watch the course VSL","href":"https://player.vimeo.com/video/1229693804?h=387686400"}]'::jsonb,0,ARRAY[]::text[]) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "experiences" ("slug","role","place","type","image","image_alt","text","details","links","sort_order","related_project_slugs") VALUES ('marketing-manager-gezahegn-and-elfinesh','Marketing Manager','Gezahegn and Elfinesh Hotel & Resort','Hospitality · Marketing','/images/placeholder.png','Editorial illustration of a hotel welcome space and visual campaign cards.','Worked in marketing for one of Ethiopia’s largest hotel and resort operations, building experience in positioning a hospitality brand, communicating value, and connecting an organization with its audience.','["Worked on brand positioning and customer communication in hospitality.","Built experience connecting the hotel and resort’s offering with its audience."]'::jsonb,'[]'::jsonb,1,ARRAY[]::text[]) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "experiences" ("slug","role","place","type","image","image_alt","text","details","links","sort_order","related_project_slugs") VALUES ('hawassa-university-computer-science','Bachelor of Science in Computer Science','Hawassa University','Education · Computer science','/images/placeholder.png','Editorial illustration of an open computer-science book, laptop, and campus architecture.','Earned a Computer Science degree from Hawassa University, one of Ethiopia’s leading universities, building the technical foundation behind my product, systems, and software engineering work.','["Earned a Bachelor of Science in Computer Science at Hawassa University.","This education forms the technical foundation for product, systems, and software engineering work."]'::jsonb,'[]'::jsonb,2,ARRAY[]::text[]) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "experiences" ("slug","role","place","type","image","image_alt","text","details","links","sort_order","related_project_slugs") VALUES ('founder-startup-builder','CEO and Startup Builder','EthioVista · Deborah School · TenaSew · Negus Gebeya','Leadership · Ethiopia-rooted startups','/images/placeholder.png','Editorial illustration of connected product panels for travel, education, wellness, and commerce.','Lead and build Ethiopia-rooted startups across travel, education, wellness, and commerce. Each product starts with a local problem, a clear user workflow, and a practical path from idea to live experience.','["Lead and build products across travel, education, wellness, and commerce.","Shape each venture from a local problem and user workflow through architecture, launch, and iteration."]'::jsonb,'[]'::jsonb,3,ARRAY['ethiovista-ethiopia-travel-platform','deborah-education-saas','tenasew-wellness-platform','negus-gebeya-marketplace']::text[]) ON CONFLICT ("slug") DO NOTHING;
